/**
 * Generates src/content/countries.generated.ts and copies flag SVGs into public/flags.
 *
 * Inputs:
 *   vendor/countries/countries.json   (mledoze/countries, ODbL 1.0)
 *   vendor/flag-icons/flags/4x3/*.svg (lipis/flag-icons, MIT)
 *   src/content/geoEditorial.ts       (our editorial layer)
 *
 * Usage: bun scripts/build-geo.ts [path-to-vendor-dir]
 * The generated file is committed, so the app builds without the vendor checkouts.
 */
import { readFileSync, writeFileSync, mkdirSync, copyFileSync, existsSync } from 'node:fs';
import { join } from 'node:path';
import type { Country, CapitalEntry, Region } from '../src/content/types';
import {
  INCLUDED_CODES, TIER_1, TIER_2, FLAG_FACTS, CAPITAL_OVERRIDES, CAPITAL_VARIANTS, STATUS_NOTES, EXTRA_ALIASES,
} from '../src/content/geoEditorial';

const vendor = process.argv[2] ?? join(import.meta.dir, '../../vendor');
const root = join(import.meta.dir, '..');
const raw = JSON.parse(readFileSync(join(vendor, 'countries/countries.json'), 'utf8')) as any[];

const byCca3 = new Map(raw.map((c) => [c.cca3, c]));
const included = new Set(INCLUDED_CODES);
const t1 = new Set(TIER_1);
const t2 = new Set(TIER_2);

const out: Country[] = [];
for (const code of INCLUDED_CODES) {
  const c = raw.find((x) => x.cca2.toLowerCase() === code);
  if (!c) throw new Error(`Missing dataset entry for ${code}`);
  const region = c.region as Region;
  if (!['Africa', 'Americas', 'Asia', 'Europe', 'Oceania'].includes(region)) throw new Error(`Odd region for ${code}: ${region}`);

  const ov = CAPITAL_OVERRIDES[code];
  let capitals: CapitalEntry[] = ov
    ? ov.capitals.map((cap) => ({ ...cap }))
    : (c.capital as string[]).map((name) => ({ name, credit: 'full' as const }));
  capitals = capitals.map((cap) => {
    const extra = CAPITAL_VARIANTS[cap.name] ?? [];
    const variants = [...new Set([...(cap.variants ?? []), ...extra])];
    return variants.length ? { ...cap, variants } : { ...cap, variants: undefined };
  });

  const aliases = new Set<string>();
  for (const a of [c.name.official, ...(c.altSpellings ?? []), ...(EXTRA_ALIASES[code] ?? [])]) {
    if (typeof a !== 'string') continue;
    if (a.length <= 3 && a.toUpperCase() === a) continue; // skip codes like "FR"
    if (a !== c.name.common) aliases.add(a);
  }

  const borders = (c.borders as string[])
    .map((b) => byCca3.get(b))
    .filter((b) => b && included.has(b.cca2.toLowerCase()))
    .map((b) => b.name.common as string);

  out.push({
    code,
    name: c.name.common,
    officialName: c.name.official,
    aliases: [...aliases],
    region,
    subregion: c.subregion || region,
    capitals,
    capitalNote: ov?.note,
    statusNote: STATUS_NOTES[code],
    landlocked: !!c.landlocked,
    borders,
    areaKm2: Math.round(c.area),
    tier: t1.has(code) ? 1 : t2.has(code) ? 2 : 3,
    flagFact: FLAG_FACTS[code],
  });
}

// Friendlier display names where the dataset's common name is unusual for English speakers.
const DISPLAY: Record<string, string> = { va: 'Vatican City', ps: 'Palestine', cz: 'Czechia', ci: "Côte d'Ivoire" };
for (const c of out) if (DISPLAY[c.code] && c.name !== DISPLAY[c.code]) {
  c.aliases.push(c.name);
  c.name = DISPLAY[c.code];
}

out.sort((a, b) => a.name.localeCompare(b.name));

const header = `/* AUTO-GENERATED by scripts/build-geo.ts — do not edit by hand.
 * Country data: mledoze/countries (Open Database License 1.0), with the Curious Minds editorial layer in geoEditorial.ts.
 */
import type { Country } from './types';

export const COUNTRIES: Country[] = `;
writeFileSync(join(root, 'src/content/countries.generated.ts'), header + JSON.stringify(out, null, 1) + ';\n');

const flagDir = join(root, 'public/flags');
mkdirSync(flagDir, { recursive: true });
for (const c of out) {
  const src = join(vendor, 'flag-icons/flags/4x3', `${c.code}.svg`);
  if (!existsSync(src)) throw new Error(`Missing flag ${c.code}`);
  copyFileSync(src, join(flagDir, `${c.code}.svg`));
}
console.log(`Wrote ${out.length} countries and flags.`);
